import { createRequire } from 'node:module';
const decode = createRequire(import.meta.url)('./index.js');
let fail = 0;
const eq = (name, a, b) => { const ok = a === b; console.log((ok ? 'PASS ' : 'FAIL ') + name); if (!ok) { fail++; console.log('  got', JSON.stringify(a), 'want', JSON.stringify(b)); } };
eq('plain', decode('hello'), 'hello');
eq('spaces', decode('a+b%20c'), 'a b c');
eq('utf8', decode('%E2%9C%A8'), '✨');
eq('bad escape kept', decode('100%'), '100%');
eq('bad byte replaced, rest decoded', decode('%FF%E2%9C%A8x'), '�✨x');
eq('mixed', decode('roam%2F123%ZZ'), 'roam/123%ZZ');
const t = Date.now();
decode('%C2'.repeat(200000) + '%');
decode('%'.repeat(100000) + '%E0%A4%A');
const ms = Date.now() - t;
eq(`huge crafted input decodes fast (${ms}ms)`, ms < 1000, true);
process.exit(fail ? 1 : 0);
